  color: #FFFFFF !important;
  border: none !important;
  border-radius: 8px !important;
  box-shadow: none !important;
}

.grp-intro-avatar {
  border: 1px solid #E5E5E5 !important;
  box-shadow: none !important;
}

/* ==========================================
   05. 投票卡与接龙卡
   ========================================== */

.grp-interactive-card,
.grp-vote-card,
.grp-chain-card {
  background: #FFFFFF !important;
  color: #292929 !important;
  border: 1px solid #E5E5E5 !important;
  border-radius: 13px !important;
  box-shadow: 0 3px 12px rgba(0,0,0,0.045) !important;
}

.grp-card-head,
.grp-vote-head,
.grp-chain-head {
  background: #F0F0F0 !important;
  color: #292929 !important;
  border-radius: 12px 12px 0 0 !important;
}

.grp-card-icon,
.grp-card-label,
.grp-card-title,
.grp-vote-title,
.grp-chain-title {
  color: #292929 !important;
}

.grp-card-status {
  background: #E4E4E4 !important;
  color: #555555 !important;
  border-radius: 20px !important;
}

.grp-card-meta,
.grp-vote-meta,
.grp-chain-meta {
  color: #999999 !important;
}

/* 投票选项 */
.grp-vote-option {
  background: #F3F3F3 !important;
  color: #333333 !important;
  border: 1px solid transparent !important;
  border-radius: 7px !important;
}

.grp-vote-option.is-mine {
  background: #E8E8E8 !important;
  border: 1px solid #333333 !important;
}

.grp-vote-option.is-leading {
  border-color: #555555 !important;
}

.grp-vote-bar {
  background: #E7E7E7 !important;
  border-radius: 20px !important;
}

.grp-vote-option.is-leading .grp-vote-bar {
  background: #333333 !important;
}

/* 投票结束按钮 */
.grp-vote-end-btn {
  background: #292929 !important;
  color: #FFFFFF !important;
  border: none !important;
  border-radius: 7px !important;
}

/* 接龙列表 */
.grp-chain-list {
  background: #FFFFFF !important;
}

.grp-chain-entry {
  border-bottom: 1px solid #EEEEEE !important;
}

.grp-chain-index {
  color: #999999 !important;
}

.grp-chain-entry-name {
  color: #292929 !important;
  font-weight: 600 !important;
}

.grp-chain-entry-text {
  color: #666666 !important;
}

.grp-chain-entry.is-latest {
  background: #F6F6F6 !important;
}

.grp-chain-join-btn {
  background: #292929 !important;
  color: #FFFFFF !important;
  border: none !important;
  border-radius: 7px !important;
}

.grp-chain-end-btn {
  background: #EEEEEE !important;
  color: #444444 !important;
  border: 1px solid #DDDDDD !important;
  border-radius: 7px !important;
}

/* ==========================================
   06. @成员弹出列表
   ========================================== */

.grp-mention-popup {
  background: rgba(255,255,255,0.98) !important;
  border: 1px solid #E8E8E8 !important;
  border-radius: 14px !important;
  box-shadow: 0 -3px 20px rgba(0,0,0,0.08) !important;
}

.grp-mention-title {
  background: #F5F5F5 !important;
  color: #888888 !important;
  border-radius: 13px 13px 0 0 !important;
  font-size: 11px !important;
  letter-spacing: 0.5px;
}

.grp-mention-item {
  color: #292929 !important;
}

.grp-mention-item + .grp-mention-item {
  border-top: 1px solid #EEEEEE !important;
}

.grp-mention-item.is-all {
  color: #292929 !important;
  font-weight: 600 !important;
}

.grp-mention-name {
  color: #292929 !important;
}

.grp-mention-item:hover,
.grp-mention-item:active {
  background: #EEEEEE !important;
}

.grp-mention-avatar {
  border-radius: 50% !important;
}

/* ==========================================
   07. 群线下邀约
   ========================================== */

.grp-offline-invite-extra {
  background: #FFFFFF !important;
  border: 1px solid #E5E5E5 !important;
  border-radius: 13px !important;
  box-shadow: 0 3px 12px rgba(0,0,0,0.04) !important;
}

.grp-offline-roster,
.grp-offline-resolved,
.grp-offline-hint {
  color: #777777 !important;
  font-family: inherit !important;
  letter-spacing: 0 !important;
}

.grp-offline-roster-item {
  color: #333333 !important;
  border-bottom: 1px solid #EEEEEE !important;
}

.grp-offline-roster-item.is-accepted {
  color: #292929 !important;
  font-weight: 700 !important;
}

.grp-offline-roster-tag {
  background: #EEEEEE !important;
  color: #555555 !important;
  border-radius: 5px !important;
}

/* 赴约 / 出发 */
.grp-offline-btn.is-primary {
  background: #292929 !important;
  color: #FFFFFF !important;
  border: 1px solid #292929 !important;
  border-radius: 7px !important;
  box-shadow: none !important;
}

/* 婉拒 / 取消 */
.grp-offline-btn.is-secondary {
  background: #FFFFFF !important;
  color: #444444 !important;
  border: 1px solid #DADADA !important;
  border-radius: 7px !important;
  box-shadow: none !important;
}

.grp-offline-invite-extra.is-cancelled {
  opacity: 0.58;
}

/* ==========================================
   08. 群聊加载提示与系统提示
   ========================================== */

.grp-load-hint {
  color: #999999 !important;
  font-size: 11px !important;
  letter-spacing: 0.4px;
}

.grp-load-hint.is-loading {
  color: #555555 !important;
}

.msg-system {
  color: #999999 !important;
}

.timestamp-custom {
  color: #A0A0A0 !important;
}

/* ==========================================
   09. 顶栏 U 型背景
   保留原有内部控件样式
   ========================================== */

.chat-header-custom,
.chat-detail-screen .glass-header {
  border-radius: 0 0 28px 28px !important;
  overflow: hidden;
}

/* ==========================================
   10. 底栏 U 型背景
   保留输入框与按钮原有形状
   ========================================== */

.input-area-custom {
  border-radius: 28px 28px 0 0 !important;
  overflow: hidden;
}
/* =================================
   群聊顶栏：隐藏头像 + 群名称居中
   ================================= */

/* 仅隐藏顶栏头像 */
.chat-header-custom .header-avatar-container,
.chat-header-custom .chat-header-avatar,
.chat-detail-screen .glass-header .header-avatar-container,
.chat-detail-screen .glass-header .chat-header-avatar {
    display: none !important;
}

/* 群名称信息区域水平居中 */
.chat-header-custom .header-profile-section,
.chat-detail-screen .glass-header .header-profile-section {
    position: absolute !important;
    left: 50% !important;
    top: calc(50% + 20px) !important;
    transform: translate(-50%, -50%) !important;

    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;

    width: max-content !important;
    max-width: calc(100% - 150px) !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* 群名称文字居中 */
.chat-header-custom .chat-header-title,
.chat-detail-screen .glass-header .chat-header-title {
    width: 100% !important;
    text-align: center !important;
    margin: 0 !important;
}

/* 副标题也居中，但保留原始人数 */
.chat-header-custom .chat-header-subtitle,
.chat-detail-screen .glass-header .chat-header-subtitle {
    width: 100% !important;
    text-align: center !important;
    margin: 2px 0 0 !important;
}
/* =================================
   底栏图标替换 + 输入框矩形化
   ================================= */

:root {
    /* 图标替换 */
    --plus-btn-icon: url('https://imgbed.heliar.top/i/crXHM9vkPSSVEikZ_retouch_2026103112130573.png');
    --send-btn-icon: url('https://imgbed.heliar.top/i/6xYBzBNVMnxnQgMc_retouch_2026103112141294.png');
    --ai-btn-icon: url('https://imgbed.heliar.top/i/lK21e5yXWp7qAF47_retouch_2026103112201658.png');

    /* 底栏背景：整体加高 */
    --input-area-padding: 18px 16px;
    --input-area-min-height: 70px;

    /* 输入框：压低高度、改成矩形 */
    --input-box-padding: 1px 14px;
    --input-box-radius: 5px;
}

/* =================================
   输入框矩形外观
   ================================= */

.input-box-custom {
    padding: 1px 14px !important;
    border-radius: 5px !important;
    min-height: 0 !important;
}

/* =================================
   加号图标：放大、稍微上移
   不改变按钮点击区域
   ================================= */

.input-btn-plus svg,
.input-btn-plus img {
    width: 29px !important;
    height: 29px !important;
    transform: translateY(-2px) scale(1.1) !important;
}

/* =================================
   隐藏语音、表情图标
   保留原按钮点击区域
   ================================= */

.input-btn-mic svg,
.input-btn-mic img,
.input-btn-sticker svg,
.input-btn-sticker img {
    visibility: hidden !important;
}

.input-btn-mic,
.input-btn-sticker {
    visibility: visible !important;
    pointer-events: auto !important;
}
/* ===== 顶栏返回键 ===== */
.header-btn-back {
    position: relative !important;
}

.header-btn-back svg,
.header-btn-back img {
    opacity: 0 !important;
}

.header-btn-back::after {
    content: "" !important;
    position: absolute !important;
    width: 24px !important;
    height: 24px !important;
    left: 50% !important;
    top: 50% !important;
    transform: translate(-50%, -50%) !important;
    background-image: url("https://imgbed.heliar.top/i/K9hZ4iRcry21Fqb9_retouch_2026103112145312.png") !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
}

/* ===== 顶栏最右侧第4个：聊天设置键 ===== */
.header-btn-info {
    position: relative !important;
}

.header-btn-info svg,
.header-btn-info img {
    opacity: 0 !important;
}

.header-btn-info::after {
    content: "" !important;
    position: absolute !important;
    width: 24px !important;
    height: 24px !important;
    left: 50% !important;
    top: 50% !important;
    transform: translate(-50%, -50%) !important;
    background-image: url("https://imgbed.heliar.top/i/YF6kEwbN1yiI8iGm_retouch_2026103112150791.png") !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
}
/* ===== 隐藏顶栏第2个：通话记录图标 ===== */
.header-btn-phone svg,
.header-btn-phone img {
    visibility: hidden !important;
}

/* ===== 隐藏顶栏第3个：视频通话图标 ===== */
.header-btn-video svg,
.header-btn-video img {
    visibility: hidden !important;
}

/* 保留按钮本身和点击区域 */
.header-btn-phone,
.header-btn-video {
    visibility: visible !important;
    pointer-events: auto !important;
}
/* ===== 输入框自定义提示文案 ===== */

/* 隐藏原始提示文字 */
.input-box-custom::placeholder {
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
    opacity: 0 !important;
}

/* 输入框为空时显示新文案 */
.input-action-bar-custom {
    position: relative !important;
}

.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::after {
    content: "正在加载中…ㅇㄱㅇ" !important;
    position: absolute !important;
    left: 16px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    color: #999 !important;
    font-size: 13px !important;
    line-height: 1 !important;
    white-space: nowrap !important;
    pointer-events: none !important;
}

/* 输入内容后隐藏自定义文案 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown))::after {
    display: none !important;
}
/* 隐藏气泡内引用，显示独立引用框 */
.msg-reply-block {
    display: none !important;
}

.msg-reply-block-detached {
    display: flex !important;
    position: relative !important;
    box-sizing: border-box !important;
    text-align: left !important;
    align-items: flex-start !important;
    line-height: 1.35 !important;
}

/* 白底黑框 + 紧凑布局 */
.chat-detail-screen {
    --reply-detached-bg: #ffffff;
    --reply-detached-border: 1.5px solid #222222;
    --reply-detached-border-left: 1.5px solid #222222;
    --reply-detached-radius: 8px;

    --reply-detached-padding: 9px 10px 6px;
    --reply-detached-gap: 2px;
    --reply-detached-margin-top: 10px;
    --reply-detached-margin-bottom: 5px;

    --reply-detached-max-width: 78%;
    --reply-detached-shadow: none;

    --reply-detached-name-color: #222222;
    --reply-detached-text-color: #777777;

    --reply-detached-me-bg: #ffffff;
    --reply-detached-me-border: 1.5px solid #222222;
    --reply-detached-me-border-left: 1.5px solid #222222;
    --reply-detached-me-name-color: #222222;
    --reply-detached-me-text-color: #777777;

    --reply-detached-them-bg: #ffffff;
    --reply-detached-them-border: 1.5px solid #222222;
