  margin-left: auto !important;
}

/* 行容器做参照 */
.chat-detail-screen .msg-bubble-wrapper.msg-them {
  position: relative !important;
}

/* 气泡整体下移 */
.chat-detail-screen .msg-bubble-wrapper.msg-them .bubble-them-custom {
  position: relative !important;
  top: 13px !important;
}

/* 折叠态：脱流，占住气泡下移空出的缝，不推气泡 */
.chat-detail-screen .msg-bubble-wrapper.msg-them .nuo-thinking-wrap:not(.is-open) {
  position: absolute !important;
  left: 0 !important;
  bottom: calc(100% - 13px) !important;
  margin: 0 !important;
  z-index: 6 !important;
}

/* 展开态：回归正常流，按原逻辑把气泡往下推 */
.chat-detail-screen .msg-bubble-wrapper.msg-them .nuo-thinking-wrap.is-open {
  position: static !important;
  margin-bottom: 2px !important;
}

/* ===== 消息间距 ===== */
:root{
  --nj-gap-in:6px;          /* 同一个人连发，气泡之间（每一条都一样） */
  --nj-gap-them-end:20px;    /* 对方说完 → 换我说 */
  --nj-gap-me-end:37px;      /* 我说完 → 换对方说（对方头像会稍微高出气泡，所以更宽） */
  --nj-gap-react:16px;       /* 有表情反应的消息额外多留的空 */
}

/* 所有消息行：先统一成连发间距 */
.msg-bubble-wrapper{
  margin-bottom:var(--nj-gap-in) !important;
}
.msg-bubble-wrapper.has-reactions{
  margin-bottom:calc(var(--nj-gap-in) + var(--nj-gap-react)) !important;
}

/* 每组最后一条（或单独一条）：和下一组之间，单独覆盖 */
.msg-bubble-wrapper.msg-them:is(.is-last,.is-single){
  margin-bottom:var(--nj-gap-them-end) !important;
}
.msg-bubble-wrapper.msg-me:is(.is-last,.is-single){
  margin-bottom:var(--nj-gap-me-end) !important;
}
.msg-bubble-wrapper.msg-them.has-reactions:is(.is-last,.is-single){
  margin-bottom:calc(var(--nj-gap-them-end) + var(--nj-gap-react)) !important;
}
.msg-bubble-wrapper.msg-me.has-reactions:is(.is-last,.is-single){
  margin-bottom:calc(var(--nj-gap-me-end) + var(--nj-gap-react)) !important;
}

/* 头像不再撑高消息行：行高只看气泡，间距就不会随气泡长短变 */
.msg-avatar-them-container{
  align-self:flex-start !important;
  margin-bottom:-200px !important;   /* 抵消它对行高的贡献，头像本身大小位置不变 */
}
.msg-bubble-wrapper{
  min-height:0 !important;
}

/* ===== 试验：用 data-sender 那一层判断「后面有没有对方消息」 ===== */
:root{
  --nj-unread-size:11px;
  --nj-unread-gap:6px;
  --nj-unread-bottom:2px;
}
[data-sender="me"]:not(:has(~ [data-sender="them"])) .msg-content-stack{
  position:relative;
}
[data-sender="me"]:not(:has(~ [data-sender="them"])) .msg-content-stack::after{
  content:"1";
  position:absolute;
  right:100%;
  margin-right:var(--nj-unread-gap);
  bottom:var(--nj-unread-bottom);
  font-size:var(--nj-unread-size);
  font-weight:700;
  line-height:1;
  color:currentColor;
  opacity:.5;
  pointer-events:none;
}

/* ===== 居中时间戳 ===== */
:root{
  --nj-ts-bg:rgba(0,0,0,.04);       /* 胶囊底色：比背景深约 4%，跟着壁纸走 */
  --timestamp-color:#111111;
  --timestamp-size:13px;
  --timestamp-weight:400;
  --timestamp-margin:6px auto 14px;
}

.timestamp-custom{
  display:flex !important;
  align-items:center !important;
  justify-content:center !important;
  width:fit-content !important;
  max-width:90% !important;
  min-height:26px !important;
  margin:var(--timestamp-margin) !important;
  padding:0 10px 0 13px !important;
  background:var(--nj-ts-bg) !important;
  border-radius:999px !important;
  text-align:center !important;
  line-height:1.2 !important;
  letter-spacing:0 !important;
}

/* 右边的小箭头 > */
.timestamp-custom::after{
  content:"";
  flex:none;
  width:5px; height:9px;
  margin-left:5px;
